import {ActionList, ActionMenu, FormControl, Label, Textarea, TextInput} from '@primer/react'
import {useEffect, useRef, useState} from 'react'

import {useTargetedEditsContext} from '../../../contexts/TargetedEditsContext'
import type {ElementPayload} from '../../../targeted-edits/types'
import {ColorPickerItem} from '../ColorPickerItem'
import {Section} from '../Section'
import {parseTailwindClassName} from '../utils/parse-tailwind-class-name'
import styles from './TargetedEditsPanel.module.css'

interface TargetedEditsPanelProps {
  element: ElementPayload
  onClose: () => void
}

const fontFamilyOptions = [
  {name: 'Default', value: null},
  {name: 'Sans serif', value: 'font-sans'},
  {name: 'Serif', value: 'font-serif'},
  {name: 'Monospace', value: 'font-mono'},
]

const fontWeightOptions = [
  {name: 'Default', value: null},
  {name: 'Thin', value: 'font-thin'},
  {name: 'Extra Light', value: 'font-extralight'},
  {name: 'Light', value: 'font-light'},
  {name: 'Normal', value: 'font-normal'},
  {name: 'Medium', value: 'font-medium'},
  {name: 'Semi Bold', value: 'font-semibold'},
  {name: 'Bold', value: 'font-bold'},
  {name: 'Extra Bold', value: 'font-extrabold'},
  {name: 'Black', value: 'font-black'},
]

const fontSizeOptions = [
  {name: 'Default', value: null},
  {name: 'xs', value: 'text-xs'},
  {name: 'sm', value: 'text-sm'},
  {name: 'base', value: 'text-base'},
  {name: 'lg', value: 'text-lg'},
  {name: 'xl', value: 'text-xl'},
  {name: '2xl', value: 'text-2xl'},
  {name: '3xl', value: 'text-3xl'},
  {name: '4xl', value: 'text-4xl'},
  {name: '5xl', value: 'text-5xl'},
  {name: '6xl', value: 'text-6xl'},
]

export function TargetedEditsPanel({element}: TargetedEditsPanelProps) {
  const {modifyJsxClassName, modifyJsxText} = useTargetedEditsContext()

  const [localText, setLocalText] = useState<string>(element.text ?? '')
  const [localClassName, setLocalClassName] = useState<string>((element.props.className as string) ?? '')

  const isEditingClassName = useRef(false)

  const location = element.location ?? element.component.location!

  const handleClassNameChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newClassName = event.target.value
    setLocalClassName(newClassName)
    modifyJsxClassName({
      filePath: location.start.filePath,
      line: location.start.line,
      column: location.start.column,
      className: newClassName,
      replace: true,
    })
  }

  const handleTextChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setLocalText(event.target.value)
  }

  useEffect(() => {
    if (element.text) {
      setLocalText(element.text)
    }
  }, [element.text])

  /**
   * This can happen when the user updated the color / background color, which changes the className of the element
   */
  useEffect(() => {
    if (element.props.className && element.props.className !== localClassName && !isEditingClassName.current) {
      setLocalClassName(element.props.className as string)
    }
  }, [element.props.className, localClassName])

  const tokens = parseTailwindClassName(localClassName)

  return (
    <>
      <div className={styles.headerContainer}>
        <div className="d-flex flex-justify-between">
          <Label>{element.tag}</Label>
        </div>
      </div>
      {element.text && (
        <Section title="Content">
          <FormControl disabled={element.editable === false}>
            <FormControl.Label visuallyHidden>Content</FormControl.Label>
            <TextInput
              block
              name="name"
              value={localText}
              placeholder="Enter name"
              onChange={handleTextChange}
              onBlur={() => {
                modifyJsxText({
                  filePath: location.start.filePath,
                  line: location.start.line,
                  column: location.start.column,
                  content: localText,
                })
              }}
            />
            {element.editable === false && (
              <FormControl.Caption>
                This content is dynamically generated and cannot be edited directly. To make changes, please make a new
                iteration.
              </FormControl.Caption>
            )}
          </FormControl>
        </Section>
      )}
      <Section title="Typography">
        <Section.Group label="Family" columns={1}>
          <FontMenu
            value={tokens.fontFamily}
            onChange={value => {
              modifyJsxClassName({
                filePath: location.start.filePath,
                line: location.start.line,
                column: location.start.column,
                className: value!,
                replace: false,
              })
            }}
            options={fontFamilyOptions}
          />
        </Section.Group>
        <Section.Group label="Weight" columns={1}>
          <FontMenu
            value={tokens.fontWeight}
            onChange={value => {
              modifyJsxClassName({
                filePath: location.start.filePath,
                line: location.start.line,
                column: location.start.column,
                className: value!,
                replace: false,
              })
            }}
            options={fontWeightOptions}
          />
        </Section.Group>
        <Section.Group label="Size" columns={1}>
          <FontMenu
            value={tokens.fontSize}
            onChange={value => {
              modifyJsxClassName({
                filePath: location.start.filePath,
                line: location.start.line,
                column: location.start.column,
                className: value!,
                replace: false,
              })
            }}
            options={fontSizeOptions}
          />
        </Section.Group>
      </Section>
      <Section title="Appearance">
        <Section.Group label="Text" columns={1}>
          <ColorPickerItem
            label="Color"
            value={tokens.textColor}
            onChange={color => {
              modifyJsxClassName({
                filePath: location.start.filePath,
                line: location.start.line,
                column: location.start.column,
                className: `text-${color.name}-${color.step}`,
                replace: false,
              })
            }}
          />
        </Section.Group>
        <Section.Group label="Background" columns={1}>
          <ColorPickerItem
            label="Color"
            value={tokens.backgroundColor}
            onChange={color => {
              modifyJsxClassName({
                filePath: location.start.filePath,
                line: location.start.line,
                column: location.start.column,
                className: `bg-${color.name}-${color.step}`,
                replace: false,
              })
            }}
          />
        </Section.Group>
        <Section.Group label="Border" columns={1}>
          <ColorPickerItem
            label="Color"
            value={tokens.borderColor}
            onChange={color => {
              modifyJsxClassName({
                filePath: location.start.filePath,
                line: location.start.line,
                column: location.start.column,
                className: `border-${color.name}-${color.step}`,
                replace: false,
              })
            }}
          />
        </Section.Group>
      </Section>

      <Section title="Advanced">
        <FormControl>
          <FormControl.Label visuallyHidden>Class</FormControl.Label>
          <Textarea
            block
            rows={3}
            value={localClassName}
            onChange={handleClassNameChange}
            resize="vertical"
            onFocus={() => (isEditingClassName.current = true)}
            onBlur={() => (isEditingClassName.current = false)}
            placeholder="Enter className"
          />
        </FormControl>
      </Section>
    </>
  )
}

const FontMenu = ({
  options,
  value,
  onChange,
}: {
  options: Array<{name: string; value: string | null}>
  value: string | null
  onChange: (value: string | null) => void
}) => {
  const selectedOption = options.find(option => option.value === value)

  return (
    <ActionMenu>
      <ActionMenu.Button size="small" alignContent="start" block>
        {selectedOption?.name || 'Default'}
      </ActionMenu.Button>
      <ActionMenu.Overlay width="auto">
        <ActionList selectionVariant="single">
          {options.map(option => (
            <ActionList.Item
              key={option.value}
              selected={option.value === value}
              onSelect={() => onChange(option.value)}
            >
              {option.name}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

try{ TargetedEditsPanel.displayName ||= 'TargetedEditsPanel' } catch {}
try{ FontMenu.displayName ||= 'FontMenu' } catch {}